        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    res = 1
    for i in range(k):
        res = res * (n - i) // (i + 1)
    return res

N = 120

def Q_weak(k):
    if k < 2 or N - k < 2:
        return 0

    # Q_weak(k, N) = C(k, 2) * C(N-k, 2)
    c_k_2 = combinations(k, 2)
    c_Nk_2 = combinations(N - k, 2)
    return c_k_2 * c_Nk_2

