# Problem: N=120 users. A weak quartet has exactly 1 friendship pair. Maximize the number of weak quartets W.
# We assume the optimal structure is a matching of size M, plus isolated vertices.
# The number of weak quartets W for a matching of size M is given by:
# W(M) = M * (C(N - 2M, 2) + C(2M - 2, 2) - (M - 1))

N = 120

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result

def W(M, N):
    if M == 0:
        return 0

    # Contribution from choosing 2 isolated vertices (from N - 2M)
    term1 = combinations(N - 2 * M, 2)

    # Contribution from choosing 2 non-adjacent vertices from the M-1 other matched pairs (2M - 2 vertices)
    if 2 * M - 2 < 2:
        term2 = 0
    else:
        # Total pairs in 2M-2 vertices is C(2M-2, 2). Number of edges is M-1. Non-edges = Total - Edges
        term2 = combinations(2 * M - 2, 2) - (M - 1)

    return M * (term1 + term2)

# Search for the maximum W
M_values = range(1, 60)
results = {}
for M in M_values:
    results[M] = W(M, N)

max_W = max(results.values())
M_opt = [M for M, w in results.items() if w == max_W]

print(f"Maximum number of weak quartets found (based on matching structure): {max_W}")
print(f"Optimizing matching size M: {M_opt[0]}")

